14	WriteBufferFromAzureBlobStorage::WriteBufferFromAzureBlobStorage(
15	    std::shared_ptr<const Azure::Storage::Blobs::BlobContainerClient> blob_container_client_,
16	    const String & blob_path_,
17	    size_t max_single_part_upload_size_,
18	    size_t buf_size_,
19	    const WriteSettings & write_settings_,
20	    std::optional<std::map<std::string, std::string>> attributes_)
21	    : BufferWithOwnMemory<WriteBuffer>(buf_size_, nullptr, 0)
22	    , blob_container_client(blob_container_client_)
23	    , max_single_part_upload_size(max_single_part_upload_size_)
24	    , blob_path(blob_path_)
25	    , write_settings(write_settings_)
26	    , attributes(attributes_)
27	{
28	}
