36	void WriteBufferFromAzureBlobStorage::finalizeImpl()
37	{
38	    if (attributes.has_value())
39	    {
40	        auto blob_client = blob_container_client->GetBlobClient(blob_path);
41	        Azure::Storage::Metadata metadata;
42	        for (const auto & [key, value] : *attributes)
43	            metadata[key] = value;
44	        blob_client.SetMetadata(metadata);
45	    }
46	
47	    const size_t max_tries = 3;
48	    for (size_t i = 0; i < max_tries; ++i)
49	    {
50	        try
51	        {
52	            next();
53	            break;
54	        }
55	        catch (const Azure::Core::RequestFailedException & e)
56	        {
57	            if (i == max_tries - 1)
58	                throw;
59	            LOG_INFO(&Poco::Logger::get("WriteBufferFromAzureBlobStorage"),
60	                     "Exception caught during finalizing azure storage write at attempt {}: {}", i + 1, e.Message);
61	        }
62	    }
63	}
64	
65	void WriteBufferFromAzureBlobStorage::nextImpl()
66	{
67	    if (!offset())
68	        return;
69	
70	    auto * buffer_begin = working_buffer.begin();
71	    auto len = offset();
72	    auto block_blob_client = blob_container_client->GetBlockBlobClient(blob_path);
73	
74	    size_t read = 0;
75	    std::vector<std::string> block_ids;
76	    while (read < len)
77	    {
78	        auto part_len = std::min(len - read, max_single_part_upload_size);
79	
80	        auto block_id = getRandomASCIIString(64);
81	        block_ids.push_back(block_id);
82	
83	        Azure::Core::IO::MemoryBodyStream tmp_buffer(reinterpret_cast<uint8_t *>(buffer_begin + read), part_len);
84	        block_blob_client.StageBlock(block_id, tmp_buffer);
85	
86	        read += part_len;
87	    }
88	
89	    block_blob_client.CommitBlockList(block_ids);
90	
91	    if (write_settings.remote_throttler)
92	        write_settings.remote_throttler->add(read);
93	}
